// ===== Núcleo: render, entrada, som, utilidades =====
const $ = id => document.getElementById(id);
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const lerp = (a, b, t) => a + (b - a) * t;
function rng(seed) {
  let s = seed >>> 0;
  return () => { s = (s + 0x6D2B79F5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}
const R = rng(20261022);
function pick(list) { let r = R(), acc = 0; for (const it of list) { acc += it.p; if (r < acc) return it; } return list[0]; }

const canvas = $('c');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.5));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.info.autoReset = false;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15; // mesma exposição das prévias das equipes
const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0x2a2f33, 25, 200);
scene.background = new THREE.Color(0x2a2f33);
const camera = new THREE.PerspectiveCamera(65, 1, 0.08, 400);
scene.add(camera);
const timeU = { value: 0 };

const hemi = new THREE.HemisphereLight(0x9aa6b0, 0x2b2a24, 0.8);
const sun = new THREE.DirectionalLight(0xffe2b8, 1.6);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
Object.assign(sun.shadow.camera, { left: -40, right: 40, top: 40, bottom: -40, near: 1, far: 220 });
sun.shadow.bias = -0.0005;
const amb = new THREE.AmbientLight(0x8890a0, 0.35);
scene.add(hemi, sun, sun.target, amb);

// Entrada
const keys = {}, pressed = {};
addEventListener('keydown', e => { if (!keys[e.code]) pressed[e.code] = true; keys[e.code] = true; if (['Space', 'Tab'].includes(e.code)) e.preventDefault(); });
addEventListener('keyup', e => { keys[e.code] = false; });
const mouse = { dx: 0, dy: 0, l: false, r: false, lPressed: false, locked: false };
canvas.addEventListener('mousedown', e => { if (e.button === 0) { if (!mouse.l) mouse.lPressed = true; mouse.l = true; } if (e.button === 2) mouse.r = true; });
addEventListener('mouseup', e => { if (e.button === 0) mouse.l = false; if (e.button === 2) mouse.r = false; });
canvas.addEventListener('contextmenu', e => e.preventDefault());
addEventListener('mousemove', e => { if (mouse.locked || (dragLook && (e.buttons & 3))) { mouse.dx += clamp(e.movementX, -150, 150); mouse.dy += clamp(e.movementY, -150, 150); } });
let dragLook = false;
document.addEventListener('pointerlockchange', () => { mouse.locked = document.pointerLockElement === canvas; });
function lockPointer() { try { const p = canvas.requestPointerLock(); if (p && p.catch) p.catch(() => { dragLook = true; }); } catch (e) { dragLook = true; } }
function wasPressed(code) { const v = pressed[code]; pressed[code] = false; return v; }
function endInputFrame() { mouse.dx = mouse.dy = 0; mouse.lPressed = false; for (const k in pressed) pressed[k] = false; }

// Som sintetizado (WebAudio). Liga no primeiro clique.
let AC = null, master = null;
function audioInit() {
  if (AC) return;
  try { AC = new (window.AudioContext || window.webkitAudioContext)(); master = AC.createGain(); master.gain.value = 0.5; master.connect(AC.destination); } catch (e) { AC = null; }
}
let noiseBuf = null;
function noise() {
  if (noiseBuf) return noiseBuf;
  noiseBuf = AC.createBuffer(1, AC.sampleRate * 1.5, AC.sampleRate);
  const d = noiseBuf.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
  return noiseBuf;
}
function sfx(kind, vol = 1, dist = 0) {
  if (!AC) return;
  const t = AC.currentTime, att = vol / (1 + dist * dist * 0.004);
  if (att < 0.01) return;
  const g = AC.createGain(); g.connect(master);
  const src = AC.createBufferSource(); src.buffer = noise();
  const f = AC.createBiquadFilter();
  src.connect(f); f.connect(g);
  const P = {
    pistola: [1800, 0.9, 0.18], escopeta: [900, 1.2, 0.35], fuzil: [1400, 1.1, 0.28], rifle: [1100, 1.3, 0.45],
    impacto: [2500, 0.25, 0.05], carne: [600, 0.35, 0.08], passo: [400, 0.08, 0.05], vidro: [5000, 0.5, 0.3],
    madeira: [700, 0.5, 0.2], recarga: [3000, 0.15, 0.06], vazio: [4000, 0.12, 0.03], explosao: [200, 1.6, 1.4],
  }[kind] || [1000, 0.5, 0.1];
  f.type = 'lowpass'; f.frequency.value = P[0] / (1 + dist * 0.01);
  g.gain.setValueAtTime(P[1] * att, t); g.gain.exponentialRampToValueAtTime(0.001, t + P[2]);
  src.start(t, Math.random()); src.stop(t + P[2] + 0.05);
}
// sons contínuos (motor, chuva, rumor da horda, rotor): um nó por nome, só o volume e o tom mudam
const LOOPS = {};
function loopSet(name, vol, freq = 0) {
  if (!AC) return;
  let L = LOOPS[name];
  if (!L) {
    if (vol < 0.002) return;
    const g = AC.createGain(), f = AC.createBiquadFilter(); g.gain.value = 0; f.connect(g); g.connect(master);
    let src;
    if (name === 'motor') { src = AC.createOscillator(); src.type = 'sawtooth'; f.type = 'lowpass'; f.frequency.value = 400; }
    else { src = AC.createBufferSource(); src.buffer = noise(); src.loop = true; f.type = name === 'chuva' ? 'highpass' : 'lowpass'; f.frequency.value = name === 'chuva' ? 2500 : name === 'rotor' ? 300 : 160; }
    if (name === 'rotor') { // batida das pás: LFO de 11 Hz no volume
      const lfo = AC.createOscillator(), lg = AC.createGain(), am = AC.createGain(); lfo.frequency.value = 11; lg.gain.value = 0.5; am.gain.value = 0.5;
      lfo.connect(lg); lg.connect(am.gain); f.disconnect(); f.connect(am); am.connect(g); lfo.start();
    }
    src.connect(f); src.start();
    L = LOOPS[name] = { g, f, src };
  }
  const t = AC.currentTime;
  L.g.gain.setTargetAtTime(vol, t, 0.15);
  if (freq && L.src.frequency) L.src.frequency.setTargetAtTime(freq, t, 0.08);
}
function grito(dist) { // grito rouco: ruído por três formantes, sem tom puro (antes soava como sirene)
  const t = AC.currentTime, att = 1 / (1 + dist * dist * 0.006);
  if (att < 0.02) return;
  const src = AC.createBufferSource(); src.buffer = noise(); const g = AC.createGain(); g.connect(master);
  const dur = 1.0 + Math.random() * 0.4;
  for (const [f0, q, v] of [[700, 6, 1], [1150, 8, 0.7], [2600, 10, 0.35]]) {
    const f = AC.createBiquadFilter(); f.type = 'bandpass'; f.Q.value = q;
    f.frequency.setValueAtTime(f0 * 1.15, t); f.frequency.linearRampToValueAtTime(f0 * 0.8, t + dur);
    const fg = AC.createGain(); fg.gain.value = v; src.connect(f); f.connect(fg); fg.connect(g);
  }
  // aspereza: modulação rápida e irregular de volume
  const lfo = AC.createOscillator(), lg = AC.createGain(); lfo.type = 'square'; lfo.frequency.value = 31 + Math.random() * 9; lg.gain.value = 0.35; lfo.connect(lg); lg.connect(g.gain);
  g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(0.9 * att, t + 0.06); g.gain.setValueAtTime(0.9 * att, t + dur * 0.6); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  src.start(t, Math.random()); src.stop(t + dur + 0.05); lfo.start(t); lfo.stop(t + dur + 0.05);
}
function voz(kind, dist = 0) { // gemido e grito sintetizados
  if (!AC) return;
  if (kind === 'grito') return grito(dist);
  const t = AC.currentTime, att = 1 / (1 + dist * dist * 0.01);
  if (att < 0.02) return;
  const o = AC.createOscillator(), g = AC.createGain(), f = AC.createBiquadFilter();
  o.type = 'sawtooth'; f.type = 'bandpass'; f.Q.value = 3;
  const base = kind === 'grito' ? 520 : kind === 'corredor' ? 300 : 95 + Math.random() * 40;
  const dur = kind === 'grito' ? 1.4 : 0.9 + Math.random() * 0.6;
  o.frequency.setValueAtTime(base, t); o.frequency.linearRampToValueAtTime(base * (kind === 'grito' ? 1.6 : 0.7), t + dur);
  f.frequency.value = base * 3;
  g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(0.25 * att, t + 0.15); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  o.connect(f); f.connect(g); g.connect(master); o.start(t); o.stop(t + dur + 0.05);
}

// ===== Mundo: quarteirão do Jardim Aurora (brief da fatia vertical) e arredores =====
// Grade de ocupação de 0,5 m (colisão de zumbi, flow field, balas) com altura por célula.
const GC = 0.5, GN = WORLD / GC;
const WORLD_MESH = {};
const occ = new Uint8Array(GN * GN);        // 0 livre, 1 sólido, 2 muro escalável, 3 porta, 4 vidro
const occH = new Float32Array(GN * GN);     // altura do que ocupa a célula
const cellOf = (x, z) => { const gx = Math.floor((x + HALF) / GC), gz = Math.floor((z + HALF) / GC); return (gx < 0 || gz < 0 || gx >= GN || gz >= GN) ? -1 : gz * GN + gx; };
function solidAt(x, z, y = 0.5) { const c = cellOf(x, z); return c < 0 || (occ[c] !== 0 && occ[c] !== 3 && occH[c] > y); }
function fillRect(x0, z0, x1, z1, kind, h) {
  const a = Math.floor((x0 + HALF) / GC), b = Math.ceil((x1 + HALF) / GC), c = Math.floor((z0 + HALF) / GC), d = Math.ceil((z1 + HALF) / GC);
  for (let gz = Math.max(0, c); gz < Math.min(GN, d); gz++) for (let gx = Math.max(0, a); gx < Math.min(GN, b); gx++) { const i = gz * GN + gx; occ[i] = kind; occH[i] = h; }
}
// borda do mundo
