// cantos entre as cenas: mata de pinheiros no estilo da galeria (tronco e duas copas cônicas), com árvores mortas na borda
{
  const r = rng(91), PN = [], MORTAS = [];
  for (const [x0, z0, x1, z1] of [[-HALF, -HALF, -CEN_Q, -CEN_Q], [CEN_Q, -HALF, HALF, -CEN_Q], [-HALF, CEN_Q, -CEN_Q, HALF], [CEN_Q, CEN_Q, HALF, HALF]])
    for (let k = 0; k < 560; k++) {
      const x = x0 + 2 + r() * (x1 - x0 - 4), z = z0 + 2 + r() * (z1 - z0 - 4);
      if (solidAt(x, z, 0.3) || onRoad(x, z, 3)) continue;
      const borda = Math.min(Math.abs(x) - CEN_Q, Math.abs(z) - CEN_Q);
      if (borda < 14 && r() < 0.5) { MORTAS.push([x, z, 0.9 + r() * 0.5]); continue; }
      PN.push([x, z, 1.3 + r() * 1.9]);
    }
  const tg = new THREE.CylinderGeometry(0.12, 0.16, 1, 6); tg.translate(0, 0.5, 0);
  const cg = new THREE.ConeGeometry(1, 1, 7);
  const PC = [0x1f3324, 0x24382a, 0x1b2d20, 0x2a3626, 0x263024];
  inst(tg, new THREE.MeshLambertMaterial({ color: 0x3a2a1c }), PN, (t, i, m) => m.compose(_p.set(t[0], 0, t[1]), _q.identity(), _s.setScalar(t[2])));
  for (const [y, sx, sy] of [[1.9, 1.1, 2.2], [3.0, 0.8, 1.8]]) {
    const cm = inst(cg, new THREE.MeshLambertMaterial({ color: 0xffffff, flatShading: true }), PN, (t, i, m) => m.compose(_p.set(t[0], y * t[2], t[1]), _q.setFromAxisAngle(_s.set(0, 1, 0), i * 1.3), _s.set(sx * t[2], sy * t[2], sx * t[2])));
    PN.forEach((t, i) => cm.setColorAt(i, _col.set(PC[(i * 3) % PC.length])));
  }
  // árvore morta: tronco torto e três galhos
  const dg = new THREE.CylinderGeometry(0.06, 0.16, 1, 5); dg.translate(0, 0.5, 0);
  const DM = []; for (const [x, z, s] of MORTAS) { DM.push([x, z, s * 4.5, 0.12, 0, 1]); for (let k = 0; k < 3; k++) DM.push([x, z, s * 2, 0.7 + k * 0.3, k * 2.1 + x, 0.55 + k * 0.12]); }
  inst(dg, new THREE.MeshLambertMaterial({ color: 0x2e2822 }), DM, (d, i, m) => m.compose(_p.set(d[0], d[2] < 3 ? 2.2 + (i % 3) * 0.6 : 0, d[1]), _q.setFromEuler(_e.set(d[3] * Math.cos(d[4]), d[4], d[3] * Math.sin(d[4]))), _s.set(d[5], d[2], d[5])));
  for (const [x, z] of PN) fillRect(x - 0.25, z - 0.25, x + 0.25, z + 0.25, 1, 6);
  for (const [x, z] of MORTAS) fillRect(x - 0.2, z - 0.2, x + 0.2, z + 0.2, 1, 4);
}

// poças de luz das cenas (lampião, vela, fogueira): disco aditivo no chão, só à noite, como as dos postes
{
  const c = document.createElement('canvas'); c.width = c.height = 64; const g = c.getContext('2d'), gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  gr.addColorStop(0, 'rgba(255,255,255,0.6)'); gr.addColorStop(0.5, 'rgba(255,255,255,0.22)'); gr.addColorStop(1, 'rgba(255,255,255,0)'); g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
  const pg = new THREE.PlaneGeometry(1, 1); pg.rotateX(-Math.PI / 2);
  const mat = new THREE.MeshBasicMaterial({ map: new THREE.CanvasTexture(c), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -3, vertexColors: false });
  WORLD_MESH.cenPools = inst(pg, mat, LUZES_CENA, (l, i, m) => m.compose(_p.set(l[0], 0.05, l[2]), _q.identity(), _s.set(Math.min(16, l[4] * 0.9), 1, Math.min(16, l[4] * 0.9))), false);
  LUZES_CENA.forEach((l, i) => WORLD_MESH.cenPools.setColorAt(i, _col.set(l[3])));
}

const CEN_MOVEL = CENARIOS.flatMap(S => S.movel);
{
  const m = WORLD_MESH.cenPools.material.clone(); m.vertexColors = false; m.color = new THREE.Color(0xffffff);
  WORLD_MESH.cenMovel = new THREE.InstancedMesh(WORLD_MESH.cenPools.geometry, m, Math.max(1, CEN_MOVEL.length));
  WORLD_MESH.cenMovel.count = CEN_MOVEL.length; scene.add(WORLD_MESH.cenMovel);
  CEN_MOVEL.forEach((l, i) => WORLD_MESH.cenMovel.setColorAt(i, _col.copy(l.color)));
}
const _cl = new THREE.Vector3();
function cenMovelUpdate() {
  CEN_MOVEL.forEach((l, i) => {
    (l.isSpotLight ? l.target : l).getWorldPosition(_cl);
    const r = l.isSpotLight ? 11 : Math.min(18, (l.distance || 20) * 0.7);
    _m.compose(_p.set(_cl.x, 0.06, _cl.z), _q.identity(), _s.set(r, 1, r)); WORLD_MESH.cenMovel.setMatrixAt(i, _m);
  });
  WORLD_MESH.cenMovel.instanceMatrix.needsUpdate = true;
}

// zumbis da prévia viram zumbis da horda quando o jogador chega perto da cena (e voltam se ele sair e a horda os levar)
const CEN_CAT = { w: 'lento', r: 'corredor', b: 'brutamonte', c: 'lento' };
let cenAtual = null, cenT = 0, cenAnunciada = null;
const ZONA_COR = new THREE.Color(), _NOITE = new THREE.Color(0x04060a);
function cenariosUpdate(dt) {
  const px = player.x, pz = player.z;
  cenAtual = null; cenT += Math.max(0, dt || 0); // o primeiro quadro pode vir com dt negativo
  let peso = 0;
  for (const S of CENARIOS) {
    const d = Math.hypot(px - S.x, pz - S.z);
    if (!S.spawned && d < 200) {
      S.spawned = true;
      for (const [x, z, t] of S.nasc) if (!zBlocked(x, z)) zSpawn(x, z, CAT[CEN_CAT[t] || 'lento']);
    } else if (S.spawned && d > 330) S.spawned = false;
    const vis = d < 260;
    if (S.root.visible !== vis) S.root.visible = vis;
    if (vis) for (const a of S.anim) a(cenT, dt);
    if (cenDentro(S, px, pz, 25)) {
      const w = clamp(Math.min(px - S.r[0], S.r[2] - px, pz - S.r[1], S.r[3] - pz) / 25 + 1, 0, 1) * clamp(Math.min(px - S.r[0], S.r[2] - px, pz - S.r[1], S.r[3] - pz) / 25 + 1, 0, 1);
      if (w > peso) { peso = w; cenAtual = S; }
    }
  }
  if (cenAtual && peso > 0.6 && cenAnunciada !== cenAtual) { cenAnunciada = cenAtual; hudMsg(cenAtual.nome, 3); } else if (!cenAtual) cenAnunciada = null;
  // pedaços longe da câmera (além da neblina) nem entram na fila de desenho
  const far = (scene.fog ? scene.fog.far : 200) + 40;
  for (const S of [CIDADE, ...CENARIOS]) for (const m of S.tiles) { const c = m.geometry.boundingSphere; m.visible = Math.hypot(c.center.x - camera.position.x, c.center.z - camera.position.z) - c.radius < far; }
  WORLD_MESH.cenPools.visible = nightF > 0.3; WORLD_MESH.cenPools.material.opacity = clamp((nightF - 0.3) * 2, 0, 1);
  WORLD_MESH.cenMovel.visible = nightF > 0.15; WORLD_MESH.cenMovel.material.opacity = clamp((nightF - 0.15) * 1.6, 0, 1);
  if (WORLD_MESH.cenMovel.visible) cenMovelUpdate();
  // neblina da cena (a da prévia), escurecida à noite
  if (cenAtual) ZONA_COR.set(cenAtual.neblina[0]).lerp(_NOITE, nightF); // à noite a neblina da prévia vai para o quase preto azulado
  if (typeof ZONA_NEBLINA !== 'undefined') {
    if (cenAtual) { ZONA_NEBLINA.cor.copy(ZONA_COR); ZONA_NEBLINA.longe = cenAtual.neblina[1]; }
    ZONA_NEBLINA.peso = peso;
  } else if (cenAtual && scene.fog) {
    scene.fog.color.lerp(ZONA_COR, peso * 0.8); scene.background.copy(scene.fog.color);
    scene.fog.far = lerp(scene.fog.far, cenAtual.neblina[1], peso); scene.fog.near = lerp(scene.fog.near, 4, peso);
  }
}
// câmera livre para as capturas de comparação com a galeria (window.__cenCam = [x, y, z, alvoX, alvoY, alvoZ])
const _cenUpd = cenariosUpdate;
cenariosUpdate = function (dt) { _cenUpd(dt); const c = window.__cenCam; if (c) { camera.position.set(c[0], c[1], c[2]); camera.lookAt(c[3], c[4], c[5]); if (c[6] && camera.fov !== c[6]) { camera.fov = c[6]; camera.updateProjectionMatrix(); } } };

// ===== Interiores do quarteirão: paredes, portas com vida e tábuas, móveis-contêiner (brief da fatia, seção 3) =====
const DOORS = [];       // {x,z,ax,w,hp,hpMax,open,broken,planks,b,hinge}
const CONTS = [];       // {x,z,tipo,nome,b,items,opened,lugar}
const doorAt = new Int16Array(GN * GN).fill(-1);
const WALLMESH = [];    // [x0,z0,x1,z1,h,cor]
const FURN = [];        // [x,z,w,d,h,cor]
const FLOORS = [];
const PORTA_VIDA = 300, TABUA_VIDA = 150;

function addWall(x0, z0, x1, z1, h, cor) { fillRect(x0, z0, x1, z1, 1, h); WALLMESH.push([x0, z0, x1, z1, h, cor]); }
function addDoor(x, z, ax, w, b) { // ax: a porta corre ao longo de x (parede frontal/traseira) ou z
  const i = DOORS.length;
  const d = { x, z, ax, w, hp: PORTA_VIDA, hpMax: PORTA_VIDA, open: false, broken: false, planks: 0, b, ang: 0 };
  DOORS.push(d);
  const x0 = ax === 'x' ? x - w / 2 : x - 0.1, x1 = ax === 'x' ? x + w / 2 : x + 0.1, z0 = ax === 'x' ? z - 0.1 : z - w / 2, z1 = ax === 'x' ? z + 0.1 : z + w / 2;
  d.rect = [x0, z0, x1, z1];
  fillRect(x0, z0, x1, z1, 5, 2.2);
  const a = Math.floor((x0 + HALF) / GC), bb = Math.ceil((x1 + HALF) / GC), c = Math.floor((z0 + HALF) / GC), e = Math.ceil((z1 + HALF) / GC);
  for (let gz = c; gz < e; gz++) for (let gx = a; gx < bb; gx++) doorAt[gz * GN + gx] = i;
  return d;
}
function setDoor(d, open) { d.open = open; fillRect(...d.rect, open || d.broken ? 3 : 5, 2.2); }
function addCont(x, z, w, dd, h, tipo, nome, b, cor, lugar) {
  FURN.push([x, z, w, dd, h, cor]);
  fillRect(x - w / 2, z - dd / 2, x + w / 2, z + dd / 2, 1, h);
  CONTS.push({ x, z, tipo, nome, b, items: null, opened: false, lugar, h });
}

for (const b of BUILDINGS) {
  if (!b.enter) continue;
  const t = 0.2, H = b.h, cor = b.cor;
  const front = b.frente < 0 ? b.z + b.d : b.z, back = b.frente < 0 ? b.z : b.z + b.d, cx = b.x + b.w / 2;
  const casa = b.tipo === 'casa';
  const dw = casa ? 1.0 : 2.0;
  // parede da frente com porta, fundos (casa: porta dos fundos), laterais
  addWall(b.x, front - t / 2, cx - dw / 2, front + t / 2, H, cor); addWall(cx + dw / 2, front - t / 2, b.x + b.w, front + t / 2, H, cor);
  b.porta = addDoor(cx, front, 'x', dw, b);
  if (casa) { const bx = b.x + b.w * 0.75; addWall(b.x, back - t / 2, bx - 0.5, back + t / 2, H, cor); addWall(bx + 0.5, back - t / 2, b.x + b.w, back + t / 2, H, cor); b.fundos = addDoor(bx, back, 'x', 1.0, b); }
  else addWall(b.x, back - t / 2, b.x + b.w, back + t / 2, H, cor);
  addWall(b.x - t / 2, b.z, b.x + t / 2, b.z + b.d, H, cor); addWall(b.x + b.w - t / 2, b.z, b.x + b.w + t / 2, b.z + b.d, H, cor);
  FLOORS.push(b);
  const inward = b.frente < 0 ? -1 : 1; // de frente para dentro
  const zf = front + inward * 0.6, zb = back - inward * 0.6;
  if (casa) {
    // divisória no meio: sala na frente, cozinha/quarto/banheiro atrás
    const zm = (front + back) / 2, ddx = b.x + b.w * 0.3;
    addWall(b.x, zm - t / 2, ddx - 0.5, zm + t / 2, H, 0xd8d0bc); addWall(ddx + 0.5, zm - t / 2, b.x + b.w, zm + t / 2, H, 0xd8d0bc);
    addDoor(ddx, zm, 'x', 1.0, b);
    addCont(b.x + 0.7, zb, 0.7, 0.7, 1.8, 'geladeira', 'Geladeira', b, 0xe8e8e2, 'casa');
    addCont(b.x + 1.8, zb, 1.2, 0.6, 0.9, 'cozinha', 'Armário de cozinha', b, 0x8a6a4a, 'casa');
    addCont(b.x + b.w - 0.5, zb - inward * 1.2, 0.6, 1.4, 2.0, 'guarda', 'Guarda-roupa', b, 0x6a4a32, 'casa');
    addCont(b.x + b.w - 0.45, (zm + back) / 2 + inward * 0.9, 0.5, 0.5, 0.6, 'gaveta', 'Criado-mudo', b, 0x7a5a3a, 'casa');
    addCont(b.x + b.w * 0.5, zb, 0.6, 0.35, 1.4, 'banheiro', 'Armário do banheiro', b, 0xdedad0, 'casa');
    addCont(b.x + 0.5, zf + inward * 0.9, 0.5, 1.4, 1.6, 'estante', 'Estante', b, 0x5a4030, 'casa');
    if (b.nome === 'Casa 1' || b.nome === 'Casa 6') addCont(b.x + b.w - 0.6, zf + inward * 0.5, 0.6, 1.2, 1.0, 'bancada', 'Bancada de ferramentas', b, 0x4a4a46, 'casa');
  } else {
    const lugar = b.tipo === 'mercado' ? 'merc' : 'farm';
    for (let k = 0; k < 3; k++) addCont(b.x + 2.5 + k * 3.5, (front + back) / 2, 2.6, 0.6, 1.8, 'prateleira', b.tipo === 'mercado' ? 'Prateleira' : 'Prateleira de remédios', b, 0x7a7a72, lugar);
    addCont(b.x + b.w - 1.2, zf + inward * 0.6, 1.6, 0.7, 1.0, 'balcao', 'Balcão do caixa', b, 0x5a4a3a, lugar);
    if (b.tipo === 'mercado') addCont(b.x + 0.6, zb, 0.8, 2.4, 2.0, 'geladeira', 'Geladeira de bebidas', b, 0xc8d0d8, lugar);
  }
}

// ----- malhas: paredes, piso, forro, móveis, portas, tábuas -----
{
  const box = new THREE.BoxGeometry(1, 1, 1); box.translate(0, 0.5, 0);
  const wm = inst(box, new THREE.MeshLambertMaterial({ color: 0xffffff }), WALLMESH, (w, i, m) => m.compose(_p.set((w[0] + w[2]) / 2, 0, (w[1] + w[3]) / 2), _q.identity(), _s.set(w[2] - w[0], w[4], w[3] - w[1])));
  WALLMESH.forEach((w, i) => wm.setColorAt(i, _col.set(w[5])));
  const fl = inst(box, new THREE.MeshLambertMaterial({ color: 0xffffff }), FLOORS, (b, i, m) => m.compose(_p.set(b.x + b.w / 2, 0.005, b.z + b.d / 2), _q.identity(), _s.set(b.w, 0.03, b.d)), false);
  FLOORS.forEach((b, i) => fl.setColorAt(i, _col.set(b.tipo === 'casa' ? 0x7a5a3c : 0x9a958a)));
  inst(box, new THREE.MeshLambertMaterial({ color: 0xcfc8b8 }), FLOORS, (b, i, m) => m.compose(_p.set(b.x + b.w / 2, b.h - 0.05, b.z + b.d / 2), _q.identity(), _s.set(b.w + 0.3, 0.12, b.d + 0.3)));
  const fm = inst(box, new THREE.MeshLambertMaterial({ color: 0xffffff }), FURN, (f, i, m) => m.compose(_p.set(f[0], 0, f[1]), _q.identity(), _s.set(f[2], f[4], f[3])));
  FURN.forEach((f, i) => fm.setColorAt(i, _col.set(f[5])));
  // janelas pintadas nas fachadas das casas (vidro escuro, algumas com luz)
  const wins = [];
  for (const b of FLOORS) for (const zz of [b.z - 0.11, b.z + b.d + 0.11]) for (let k = 1; k < b.w / 3; k++) wins.push([b.x + k * 3 - (k * 3 > b.w / 2 - 0.8 && k * 3 < b.w / 2 + 0.8 ? 1.4 : 0), zz]);
  inst(new THREE.BoxGeometry(1.0, 1.1, 0.04), new THREE.MeshLambertMaterial({ color: 0x1c2328 }), wins, (w, i, m) => m.makeTranslation(w[0], 1.6, w[1]), false);
}
const doorGeo = new THREE.BoxGeometry(1, 2.15, 0.06); doorGeo.translate(0.5, 1.075, 0);
const doorMesh = new THREE.InstancedMesh(doorGeo, new THREE.MeshLambertMaterial({ color: 0x6a4a2c }), DOORS.length); doorMesh.castShadow = true; scene.add(doorMesh);
const plankGeo = new THREE.BoxGeometry(1, 0.18, 0.05);
const plankMesh = new THREE.InstancedMesh(plankGeo, new THREE.MeshLambertMaterial({ color: 0x9a7a52 }), DOORS.length * 3); plankMesh.count = 0; scene.add(plankMesh);
function doorsRender(dt) {
  cenariosUpdate(dt);
  let pk = 0;
  DOORS.forEach((d, i) => {
    const target = d.broken ? 1.5 : d.open ? 1.45 : 0;
    d.ang = lerp(d.ang, target, Math.min(1, dt * 8));
    const hx = d.ax === 'x' ? d.x - d.w / 2 : d.x, hz = d.ax === 'x' ? d.z : d.z - d.w / 2;
    const base = d.ax === 'x' ? 0 : -Math.PI / 2;
    const dmg = 1 - d.hp / d.hpMax; // porta cedendo em 3 estágios (66/33/0%)
    _m.compose(_p.set(hx, d.broken ? -0.9 : 0, hz), _q.setFromEuler(_e.set(d.broken ? 1.4 : (dmg > 0.66 ? 0.05 : 0), base - d.ang, dmg > 0.33 ? 0.04 : 0)), _s.set(d.w, 1, 1));
    doorMesh.setMatrixAt(i, _m);
    for (let k = 0; k < d.planks; k++) {
      _m.compose(_p.set(d.x, 0.7 + k * 0.55, d.z), _q.setFromEuler(_e.set(0, d.ax === 'x' ? 0 : Math.PI / 2, (k - 1) * 0.15)), _s.set(d.w + 0.4, 1, 1));
      plankMesh.setMatrixAt(pk++, _m);
    }
  });
  doorMesh.instanceMatrix.needsUpdate = true; plankMesh.count = pk; plankMesh.instanceMatrix.needsUpdate = true;
}
// zumbi batendo na porta: 10 por golpe a cada 1,5 s (Brutamonte 3×) + pressão de quem está atrás
function doorHit(di, dano) {
  const d = DOORS[di];
  if (d.open || d.broken) return;
  d.hp -= dano;
  if (R() < 0.3) sfx('madeira', 0.8, Math.hypot(d.x - player.x, d.z - player.z));
  if (d.planks && d.hp < d.hpMax - d.planks * TABUA_VIDA + TABUA_VIDA * (d.planks - 1)) d.planks = Math.max(0, d.planks - 1);
  if (d.hp <= 0) { d.broken = true; d.planks = 0; setDoor(d, true); emitNoise(d.x, d.z, 30); sfx('madeira', 1.5, Math.hypot(d.x - player.x, d.z - player.z)); fxDust(d.x, 1, d.z, 0x8a6a4a); if (Math.hypot(d.x - player.x, d.z - player.z) < 25) hudMsg('A porta cedeu!', 2); }
}
// zumbis dentro das casas (1 em cada 3) e porta fechada
const insideSpawns = [];
FLOORS.forEach((b, k) => { if (b.tipo === 'casa' && k % 3 === 1) insideSpawns.push([b.x + b.w * 0.5, b.z + b.d * (b.frente < 0 ? 0.25 : 0.75)]); });

// ===== Corpo arredondado (Guia de estilo) com animação na GPU, mesmo esqueleto para humano e zumbi =====
// Ossos: 0 tronco/quadril, 1 cabeça, 2/3 braço E/D, 4/5 coxa E/D, 6 olhos, 7/8 antebraço E/D, 9/10 canela E/D, 11 mandíbula
// Material por vértice: 0 pele, 1 camisa, 2 calça, 3 olho, 4 cabelo, 5 sapato
const J = { // juntas (m), altura base 1,80
  quadril: [0, 0.95, 0], pescoco: [0, 1.52, 0], ombroE: [-0.24, 1.44, 0], ombroD: [0.24, 1.44, 0],
  cotoveloE: [-0.27, 1.13, 0], cotoveloD: [0.27, 1.13, 0], coxaE: [-0.1, 0.92, 0], coxaD: [0.1, 0.92, 0],
  joelhoE: [-0.1, 0.5, 0], joelhoD: [0.1, 0.5, 0],
};
function tagGeo(geo, bone, pivot, mat, parent = [0, 0, 0]) {
  geo = geo.index ? geo.toNonIndexed() : geo;
  const n = geo.attributes.position.count;
  geo.setAttribute('bone', new THREE.Float32BufferAttribute(new Float32Array(n).fill(bone), 1));
  const vc = new Float32Array(n * 4); for (let i = 0; i < n; i++) vc[i * 4 + 3] = mat;
  geo.setAttribute('vcol', new THREE.Float32BufferAttribute(vc, 4));
  const pv = new Float32Array(n * 3), pp = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { pv.set(pivot, i * 3); pp.set(parent, i * 3); }
  geo.setAttribute('pivot', new THREE.Float32BufferAttribute(pv, 3));
  geo.setAttribute('ppivot', new THREE.Float32BufferAttribute(pp, 3));
  geo.deleteAttribute('uv');
  return geo;
}
function mergeBody(list) {
  let n = 0; for (const g of list) n += g.attributes.position.count;
  const out = new THREE.BufferGeometry();
  for (const [name, size] of [['position', 3], ['normal', 3], ['bone', 1], ['vcol', 4], ['pivot', 3], ['ppivot', 3]]) {
    const arr = new Float32Array(n * size); let o = 0;
    for (const g of list) { arr.set(g.attributes[name].array, o); o += g.attributes[name].array.length; }
    out.setAttribute(name, new THREE.BufferAttribute(arr, size));
  }
  out.computeBoundingSphere();
  return out;
}
