    Brutamonte:{s:1.42,bulk:1.32,lean:.3,armL:-.4,armR:-.25,elbL:-.35,elbR:-.25,legL:-.12,legR:.12,kneeL:.12,kneeR:.12,headX:-.2,headZ:0,neck:-.07,drop:-.02},
