    if(O.vest){const v=add(U,CYL(.275,.24,.48,24),M(O.vest),0,1.3,0);v.scale.set(1.12,1,.7);for(let i=0;i<3;i++)add(U,geoBox(.11,.13,.05),M(O.vest),-.15+i*.15,1.17,.17)}
