const _dc0 = new THREE.Color(), _dc1 = new THREE.Color();

function fxBlood(x, y, z, idade, ml, morte) {
  if (!idade || idade.sangue === 0) { // Decrépito: pó preto
    for (let k = 0; k < 10; k++) pAdd(x, y, z, (R() - .5) * 2, R() * 1.5, (R() - .5) * 2, 0.8, 0x1a1612, 0.05);
    return;
  }
  const vol = ml * idade.sangue, n = Math.min(40, 6 + vol / 12);
  const toCam = Math.atan2(x - player.x, z - player.z);
  for (let k = 0; k < n; k++) {
    const a = toCam + (R() - 0.5) * 1.2, s = 1.5 + R() * 3;
    pAdd(x, y, z, Math.sin(a) * s, R() * 2.5, Math.cos(a) * s, 1.5, idade.cor, 0.035 + R() * 0.03, 1, idade.seco);
  }
  const dry = idade === IDADES[0] ? 600 : 360;
  // respingo no chão atrás do alvo, esticado na direção do tiro (o impacto mostra de onde veio)
  if (vol >= 20) for (let k = 0, m = vol > 80 ? 3 : 1; k < m; k++) { const d = 0.6 + R() * 1.8, a = toCam + (R() - 0.5) * 0.9; decalAdd(x + Math.sin(a) * d, z + Math.cos(a) * d, 0.16 + Math.min(0.35, vol / 300) * (0.5 + R() * 0.7), a, 1.5 + R() * 0.7, idade.cor, idade.seco, dry); }
  // poça do corpo: nasce embaixo do tronco e cresce
  if (morte) decalAdd(x + Math.sin(toCam) * 0.45, z + Math.cos(toCam) * 0.45, Math.min(1.9, 0.7 + Math.sqrt(vol) / 10), R() * 6.28, 1.25, idade.cor, idade.seco, dry, 1);
}
