  Object.assign(L, { x: Z.x[i], y: regiao >= 4 ? 0.5 : 1.2, z: Z.z[i], vx: (R() - .5) * 3, vy: 2 + R() * 2, vz: (R() - .5) * 3, rx: R() * 6, rz: R() * 6, w: (R() - .5) * 10, t: 0, rest: false, len: regiao >= 4 ? 1.3 : 1, col: regiao >= 4 ? 0x2c3340 : Z.col[i] }); // manga ou calça do dono
